/bin/bash -lc "python3 - <<'EOF'
p='src/redux/actions/cartActions.js'
s=open(p, 'rb').read().decode('utf-8')
old='''        param = { \"attributes\": selectedProductOptions, \"product\": item.sku, \"quantity\": quantityCount, \"voucher\": promoCode }
      } else {
        param = { \"product\": item.sku, \"quantity\": quantityCount, \"voucher\": promoCode }
      }
'''
new='''        param = { \"attributes\": selectedProductOptions, \"product\": item.sku, \"quantity\": quantityCount }
      } else {
        param = { \"product\": item.sku, \"quantity\": quantityCount }
      }
      if (promoCode) {
        param.voucher = promoCode;
      }
'''
assert old in s
s=s.replace(old,new)
open(p,'w',encoding='utf-8').write(s)
EOF
sed -n '15,40p' src/redux/actions/cartActions.js"
